  'للمشاوي', 'للحلويات', 'العربي', 'العربية', 'الحلال', 'عربي', 'عربية', 'حلال',
  // English
  'restaurant', 'restaurants', 'grill', 'grille', 'cafe', 'coffee', 'bakery',
  'sweets', 'market', 'supermarket', 'grocery', 'store', 'shop', 'center',
