  ln: 'ln', 'ln.': 'ln', lane: 'ln',
  hwy: 'hwy', 'hwy.': 'hwy', highway: 'hwy',
  fwy: 'fwy', 'fwy.': 'fwy', freeway: 'fwy',
  pkwy: 'pkwy', parkway: 'pkwy',
